template <typename T>
	requires std::is_nothrow_destructible_v<T>
class Stack {
  public:
	Stack()
		: _cap(0)
		, _size(0)
		, _data(nullptr) {}

	// omit deep-copy
	// Stack(const Stack& other)			 = delete;
	// Stack& operator=(const Stack& other) = delete;
	Stack(Stack&& other) noexcept
		: _data(other._data)
		, _cap(other._cap)
		, _size(other._size) {
		other._data = nullptr;
		other._cap = other._size = 0;
	}

	Stack& operator=(Stack&& other) noexcept {
		if(this != &other) {
			for_each(_data, _data + _size, [](T& value) { value.~T(); });
			_data		= other._data;
			_cap		= other._cap;
			_size		= other._size;
			other._data = nullptr;
			other._cap = other._size = 0;
		}
		return *this;
	}

	~Stack() {
		std::for_each(_data, _data + _size, [](T& value) { value.~T(); });
		deallocate(_data);
	}

	T& top() {
		if(_size == 0) {
			throw std::out_of_range("Stack::top on empty stack");
		}
		return _data[_size - 1];
	}

	const T& top() const {
		if(_size == 0) {
			throw std::out_of_range("Stack::top on empty stack");
		}
		return _data[_size - 1];
	}

	void pop() {
		if(_size == 0) {
			throw std::out_of_range("Stack::pop on empty stack");
		}
		_data[--_size].~T();
	}

	// void push(T&& value) { emplace(std::move(value)); }
	// void push(const T& value) { emplace(value); }
	// merge to single method using reference collapsing
	template <typename U>
	void push(U&& value) {
		emplace(std::forward<U>(value));
	}

	template <typename... Args>
	void emplace(Args&&... args) {
		if(_size == _cap) {
			grow(_cap ? _cap * 2 : 1);
		}
		::new(static_cast<void*>(_data + _size)) T(std::forward<Args>(args)...);
		_size++;
	}

	[[nodiscard]] std::size_t size() const noexcept { return _size; }

	[[nodiscard]] bool empty() const noexcept { return _size == 0; }

  private:
	static T* allocate(std::size_t newCap) {
		if(newCap > static_cast<std::size_t>(-1) / sizeof(T)) {
			throw std::length_error("Stack::grow capacity overflow");
		}
		if constexpr(alignof(T) > __STDCPP_DEFAULT_NEW_ALIGNMENT__) {
			return static_cast<T*>(::operator new(newCap * sizeof(T), std::align_val_t(alignof(T))));
		} else {
			return static_cast<T*>(::operator new(newCap * sizeof(T)));
		}
	}

	static void deallocate(T* data) noexcept {
		if constexpr(alignof(T) > __STDCPP_DEFAULT_NEW_ALIGNMENT__) {
			::operator delete(data, std::align_val_t(alignof(T)));
		} else {
			::operator delete(data);
		}
	}

	void grow(std::size_t newCap) {
		T*			newData = allocate(newCap);
		std::size_t i		= 0;
		try {
			for(; i < _size; i++) {
				::new(static_cast<void*>(newData + i)) T(std::move_if_noexcept(_data[i]));
			}
			// } catch(const std::exception& e) {  // too small range cover
		} catch(...) {
			// rollback: destroy what was built, free the NEW buffer, keep old state intact
			for(std::size_t j = 0; j < i; j++) {
				newData[j].~T();
			}
			deallocate(newData);
			throw;
		}
		// commit: only noexcept operations from here on
		for(std::size_t j = 0; j < _size; j++) {
			_data[j].~T();
		}
		deallocate(_data);
		_data = newData;
		_cap  = newCap;
	}

	T*			_data;
	std::size_t _cap;
	std::size_t _size;
};
